<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import type { TeachingLevel } from '../../shared/tutorialProtocol'
import type { GameKind } from '../../shared/protocol'
import { GAME_DEFINITIONS } from '../../shared/gameCatalog'
import { useTeachingGame } from '../tutorials/useTeachingGame'
import TutorialAnimationStage from './TutorialAnimationStage.vue'
import BrandMark from './BrandMark.vue'
import AppIcon from './AppIcon.vue'

const props = withDefaults(defineProps<{ game: GameKind; level?: TeachingLevel; live?: boolean; opposed?: boolean }>(), { level: 'basic' })
const paged = computed(() => ['xiangqi','chess','go','gomoku'].includes(props.game))
const courseTitle = computed(() => props.game === 'go' ? props.level === 'advanced' ? '进阶教程' : '基础教程' : '动画教程')
const emit = defineEmits<{ close: [] }>()
const root = ref<HTMLElement | null>(null), directory = ref(false), directoryPage = ref(0), viewportHeight=ref(innerHeight)
const directorySize=computed(()=>viewportHeight.value<=650?4:viewportHeight.value<=900?6:10)
const directoryClips=computed(()=>paged.value?data.value?.clips.slice(directoryPage.value*directorySize.value,(directoryPage.value+1)*directorySize.value):data.value?.clips)
function measure():void { viewportHeight.value=innerHeight;directoryPage.value=Math.min(directoryPage.value,Math.max(0,Math.ceil((data.value?.total??0)/directorySize.value)-1)) }
const player = useTeachingGame(props.game,props.level)
const { data, clip, stage, error, notice, progress, elapsed, duration, watched, loading } = player
const caption = computed(() => { const pos = player.position.value; return pos?.frame?.combat && pos.fraction < .66 ? '棋子沿实际路线移动，到达目标后按交战规则处理。' : pos?.frame?.caption ?? '先观察局面，动画将自动演示关键动作。' })
const beat = computed(() => stage.value === 'ended' ? '结果' : player.position.value?.frame?.kind === 'result' ? '结果' : player.position.value?.frame ? '关键动作' : '局面')
const chapters = computed(() => [...new Set(directoryClips.value?.map(clip => clip.chapter) ?? [])])
let previous: HTMLElement | null = null
function keydown(event: KeyboardEvent): void {
  if (event.key === 'Escape') { event.preventDefault(); event.stopImmediatePropagation(); if (directory.value) directory.value = false; else emit('close'); return }
  if (event.key !== 'Tab' || !root.value) return
  const buttons = [...root.value.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], summary, [tabindex="0"]')].filter(el => el.getClientRects().length)
  const first = buttons[0], last = buttons.at(-1)
  if (event.shiftKey && (document.activeElement === first || !root.value.contains(document.activeElement))) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
}
async function toggleDirectory(): Promise<void> { directory.value = !directory.value; if (directory.value) { directoryPage.value=Math.floor((data.value?.index??0)/directorySize.value);player.pause(); await nextTick(); root.value?.querySelector<HTMLElement>('.tutorial-directory [aria-current="true"]')?.focus() } }
function select(id: string): void { directory.value = false; player.selectClip(id) }
function explain(event: Event): void { if ((event.target as HTMLDetailsElement).open) player.pause() }
onMounted(() => { window.addEventListener('resize',measure);previous = document.activeElement instanceof HTMLElement ? document.activeElement : null; root.value?.querySelector<HTMLButtonElement>('button')?.focus(); document.addEventListener('keydown', keydown, true) })
onBeforeUnmount(() => { window.removeEventListener('resize',measure);document.removeEventListener('keydown', keydown, true); previous?.focus() })
</script>

<template>
  <Teleport to="body">
    <section ref="root" class="teaching-match-view" role="dialog" aria-modal="true" :aria-label="`${GAME_DEFINITIONS[game].name}动画教程`" :data-game="game" :data-level="level" :data-stage="stage" :data-current-clip="clip?.id" :data-elapsed="Math.floor(elapsed)">
      <header class="teaching-match-header"><div><BrandMark /><strong>{{ GAME_DEFINITIONS[game].name }} · {{ courseTitle }}</strong><span>{{ progress }}</span></div><div><span v-if="live" class="teaching-live">原对局仍在进行</span><button class="tool-button" type="button" aria-label="目录" :aria-expanded="directory" aria-controls="tutorial-directory" @click="toggleDirectory"><AppIcon name="book" /><span>目录</span></button><button class="tool-button" type="button" aria-label="退出教程" @click="emit('close')"><AppIcon name="close" /><span>返回游戏</span></button></div></header>
      <div class="teaching-main">
        <div v-if="player.needsRotation.value" class="tutorial-rotate" role="status"><AppIcon name="rotate" /><h2>{{ player.needsPortrait.value ? '把设备竖起来，看棋更清楚' : '把手机横过来，看得更清楚' }}</h2><p>{{ player.needsPortrait.value ? '棋类教程用竖屏展示。' : '纸牌教程用横屏展示。' }}转好后，点击“继续播放”接着看。</p><p>当前片段已暂停，不会漏掉演示。</p></div>
        <aside v-else class="teaching-coach" aria-live="polite">
          <div class="teaching-coach-heading"><span class="teaching-phase">{{ loading ? '连接中' : stage === 'paused' ? '已暂停' : stage === 'ended' ? '本段结束' : beat }}</span><span>{{ clip?.chapter ?? '固定局面 · 自动演示' }}</span><span v-if="clip && watched.includes(clip.id)" class="teaching-watched">已观看</span></div>
          <h2>{{ clip?.title ?? '正在准备动画片段…' }}</h2>
          <p class="teaching-instruction">{{ caption }}</p>
          <details v-if="clip" class="teaching-explanation" :key="clip.id" @toggle="explain"><summary>完整机制说明</summary><p>{{ clip.explanation }}</p></details>
          <details v-if="clip?.sources?.length" class="teaching-sources" @toggle="explain"><summary>网上进阶／高级课程（可选择观看）</summary><ul><li v-for="source in clip.sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a><p>{{ source.note }}</p></li></ul><small>检索于 2026-10-31。外站课程在新页面打开，站内教程可独立观看。</small></details>
          <p v-if="error" class="teaching-error" role="alert">{{ error }}</p><p v-if="notice" class="teaching-notice">{{ notice }}</p>
        </aside>
        <div v-if="!player.needsRotation.value" class="teaching-play-area"><TutorialAnimationStage v-if="clip" :key="clip.id" :clip="clip" :elapsed="elapsed" :reduced="player.reduced.value" :opposed="opposed" /><p v-else class="teaching-loading">正在准备动画教程…</p></div>
        <div v-if="directory" class="tutorial-directory-shade" @click="directory = false"></div>
        <nav v-if="directory" id="tutorial-directory" :class="{ 'is-paged': paged }" class="tutorial-directory" aria-label="教程目录"><div class="tutorial-directory-title"><strong>按机制选段</strong><span>{{ watched.length }} / {{ data?.total ?? 0 }} 已观看</span><button class="tool-button" type="button" aria-label="关闭目录" @click="directory = false"><AppIcon name="close" /></button></div><section v-for="chapter in chapters" :key="chapter"><h3>{{ chapter }}</h3><ol><li v-for="item in directoryClips?.filter(clip => clip.chapter === chapter)" :key="item.id"><button type="button" :data-clip="item.id" :aria-current="clip?.id === item.id ? 'true' : undefined" @click="select(item.id)"><span>{{ item.title }}</span><small>{{ watched.includes(item.id) ? '已看' : '' }}</small></button></li></ol></section><footer v-if="paged" class="tutorial-directory-pager"><button class="review-button" :disabled="directoryPage === 0" @click="directoryPage--">上一页</button><span>{{ directoryPage + 1 }} / {{ Math.ceil((data?.total ?? 0) / directorySize) }}</span><button class="review-button" :disabled="(directoryPage+1)*directorySize >= (data?.total??0)" @click="directoryPage++">下一页</button></footer></nav>
      </div>
      <div class="teaching-timeline" role="progressbar" aria-label="本段播放进度" :aria-valuenow="Math.round(elapsed / Math.max(duration, 1) * 100)" aria-valuemin="0" aria-valuemax="100"><i :style="{ width: `${elapsed / Math.max(duration, 1) * 100}%` }"></i></div>
      <footer v-if="!player.needsRotation.value" class="teaching-controls">
        <div><button class="review-button" type="button" :disabled="loading" @click="player.toggle">{{ stage === 'playing' ? '暂停' : stage === 'ended' ? '重新播放' : '继续播放' }}</button><button class="review-button" type="button" :disabled="loading" @click="player.replay"><AppIcon name="rotate" />重播</button><span class="teaching-control-note">{{ stage === 'ended' ? '结果已保留，可继续下一段' : '自动演示，无需出牌或行棋' }}</span></div>
        <div><button class="review-button" type="button" :disabled="!data || data.index === 0" @click="player.adjacent(-1)">上一段</button><button class="result-primary" type="button" :disabled="!data || data.index === data.total - 1" @click="player.adjacent(1)">下一段<AppIcon name="right" /></button></div>
      </footer>
    </section>
  </Teleport>
</template>

<style>
.teaching-sources { margin-top: 9px; color: #687e55; font-size: 12px; line-height: 1.7; }.teaching-sources summary { cursor: pointer; text-decoration: underline; text-underline-offset: 3px; }.teaching-sources ul { list-style: none; margin: 9px 0; padding: 0; }.teaching-sources li { padding: 8px 10px; margin: 6px 0; border: 1px solid #d5ddc4; border-radius: 8px; background: #eff1e3; }.teaching-sources a { color: #466c45; }.teaching-sources p { margin: 3px 0 0; font-size: 11px; }.teaching-sources small { font-size: 10px; color: #8b927c; }
.teaching-match-view { position: fixed; inset: 0; z-index: 500; display: flex; flex-direction: column; width: 100vw; height: 100dvh; box-sizing: border-box; padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left); overflow: hidden; background: #f3f2e7; color: #244b3c; font-size: 13px; }
.teaching-match-header { display: flex; align-items: center; justify-content: space-between; flex: none; min-height: 52px; padding: 8px 20px; gap: 12px; border-bottom: 1px solid #d6dcc9; }.teaching-match-header > div { display: flex; align-items: center; gap: 12px; }.teaching-match-header .brand-mark { width: 30px; height: 30px; }.teaching-match-header strong { font-family: 'Songti SC', serif; font-size: 18px; font-weight: 500; }.teaching-match-header span { color: #6d7d63; font-size: 11px; }.teaching-live { color: #9a6d43 !important; }
.teaching-main { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; }.teaching-coach { flex: none; max-height: 30dvh; overflow: auto; padding: 12px 24px 10px; border-bottom: 1px solid #d4ddc5; background: #faf9f0; }.teaching-coach-heading { display: flex; gap: 10px; align-items: center; margin-bottom: 6px; color: #7b836a; font-size: 11px; }.teaching-phase { display: inline-flex; padding: 3px 9px; border-radius: 20px; background: #e3e8d3; color: #667845; font-size: 10px; }.teaching-watched { margin-left: auto; color: #7f8e68; }
.tutorial-rotate { margin: auto; text-align: center; max-width: 320px; padding: 30px; color: #647a54; }.tutorial-rotate > svg { width: 48px; height: 48px; margin: 0 auto 20px; }.tutorial-rotate h2 { font: 24px 'Songti SC', serif; line-height: 1.6; }.tutorial-rotate p { font-size: 12px; line-height: 1.9; color: #82916f; }
.teaching-coach h2 { margin: 0 0 6px; font: 22px 'Songti SC', serif; }.teaching-instruction { margin: 0; color: #4b644a; line-height: 1.7; font-size: 13px; }.teaching-explanation { margin-top: 6px; font-size: 11px; color: #69785b; }.teaching-explanation summary { width: max-content; cursor: pointer; }.teaching-explanation p { margin: 8px 0 0; max-width: 960px; line-height: 1.8; }.teaching-error { margin: 6px 0 0; padding: 7px 10px; border-radius: 8px; background: #f4e8d9; color: #8b5135; font-size: 12px; }.teaching-notice { margin: 5px 0 0; font-size: 10px; color: #83704c; }
.teaching-play-area { position: relative; flex: 1; min-height: 0; padding: 12px 18px; }.teaching-loading { text-align: center; padding: 15vh 20px; color: #748263; }.teaching-controls { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex: none; padding: 10px 18px; border-top: 1px solid #ccd8bc; background: #faf9ef; }.teaching-controls > div { display: flex; align-items: center; gap: 8px; }.teaching-controls .review-button, .teaching-controls .result-primary { min-height: 36px; font-size: 12px; padding: 7px 13px; }.teaching-control-note { font-size: 11px; color: #7b866e; }.teaching-controls button:disabled { opacity: .4; cursor: default; }.teaching-timeline { height: 3px; background: #dce3cc; flex: none; }.teaching-timeline i { display: block; height: 100%; background: #8d9c63; }
.tutorial-directory-shade { position: absolute; inset: 0; z-index: 4; background: #163a2c44; }.tutorial-directory { position: absolute; inset: 0 auto 0 0; width: min(370px, 90%); z-index: 5; overflow: auto; background: #f9f9ee; border-right: 1px solid #c8d3b8; box-shadow: 8px 0 25px #193d3320; padding: 14px; }.tutorial-directory-title { display: flex; gap: 10px; align-items: center; padding-bottom: 10px; border-bottom: 1px solid #d4dec5; }.tutorial-directory-title > span { color: #869275; font-size: 11px; }.tutorial-directory-title > button { margin-left: auto; }.tutorial-directory h3 { font-size: 12px; color: #819266; margin: 17px 8px 6px; font-weight: 500; }.tutorial-directory ol { list-style: none; padding: 0; margin: 0; }.tutorial-directory li button { display: flex; width: 100%; padding: 11px 12px; border-radius: 9px; border: 1px solid transparent; background: transparent; text-align: left; color: #426046; font: inherit; gap: 8px; justify-content: space-between; }.tutorial-directory li button:hover { background: #e8eddc; }.tutorial-directory li button[aria-current] { background: #e4ebd5; border-color: #c2d1aa; }.tutorial-directory small { font-size: 10px; color: #8b976f; flex: none; }
@media (max-width: 560px) { .teaching-match-header { padding: 7px 12px; min-height: 46px; }.teaching-match-header strong { font-size: 15px; }.teaching-match-header > div { gap: 7px; }.teaching-match-header .brand-mark { width: 24px; height: 24px; }.teaching-live { display: none; }.teaching-match-header .tool-button span { display: none; }.teaching-coach { padding: 10px 15px; }.teaching-coach h2 { font-size: 21px; }.teaching-instruction { font-size: 12px; }.teaching-play-area { padding: 9px; }.teaching-controls { padding: 8px; gap: 6px; }.teaching-controls > div { gap: 5px; }.teaching-controls .review-button, .teaching-controls .result-primary { padding: 6px 10px; font-size: 11px; }.teaching-control-note { display: none; } }
@media (orientation: landscape) and (max-height: 550px) { .teaching-match-header { min-height: 34px; padding: 3px 14px; }.teaching-match-header strong { font-size: 14px; }.teaching-match-header .brand-mark { width: 24px; height: 24px; }.teaching-coach { position: relative; padding: 6px 16px; max-height: 28vh; }.teaching-coach-heading { margin-bottom: 2px; font-size: 10px; }.teaching-phase { padding: 1px 7px; }.teaching-coach h2 { display: inline; font-size: 17px; margin-right: 12px; }.teaching-instruction { display: inline; font-size: 11px; }.teaching-explanation { position: absolute; right: 15px; top: 5px; margin: 0; }.teaching-explanation[open] { position: static; margin-top: 5px; }.teaching-controls { padding: 4px 12px; }.teaching-controls .review-button, .teaching-controls .result-primary { min-height: 30px; padding: 4px 10px; font-size: 11px; }.teaching-play-area { padding: 6px 12px; }.teaching-control-note { font-size: 9px; } }
</style>

<style>
.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-coach { overflow: hidden; max-height: none; }.tutorial-directory.is-paged { display: flex; flex-direction: column; overflow: hidden; }.tutorial-directory-pager { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex: none; margin-top: auto; padding-top: 12px; font-size: 11px; color: #829473; }
@media (max-width:360px) { .teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-match-header .brand-mark { display: none; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-match-header strong { font-size: 13px; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-match-header { gap: 5px; padding-inline: 8px; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-match-header > div { gap: 5px; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-match-header .tool-button { padding: 5px 7px; min-height: 30px; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-controls { flex-wrap: wrap; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-controls > div { flex: 1 1 100%; justify-content: space-between; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-coach h2 { font-size: 18px; }.teaching-match-view:is([data-game="xiangqi"],[data-game="chess"]) .teaching-instruction { font-size: 11px; } }
</style>
